import * as fs from 'fs'
import type * as BuildCoreModule from '@servicenow/sdk-build-core'
import { logger } from '../../logger'

/**
 * `@servicenow/sdk-build-core` is expensive to load (~350ms — it pulls in the TypeScript compiler
 * and ts-morph via its index). `cicd` is required to stay lightweight — it never constructs a
 * Project, unlike `build`/`install` — so this is `require()`'d lazily inside each function below,
 * not imported at module scope, to avoid taxing every `cicd` subcommand (testsuite/tests, not just
 * app-repo) with that cost just for importing this file.
 */
function loadBuildCore(): typeof BuildCoreModule {
    return require('@servicenow/sdk-build-core')
}

/**
 * Defaults `--app-sys-id` from the current directory's `now.config.json` (`scopeId`) when neither
 * `--scope` nor `--app-sys-id` was provided. A Fluent project always knows its own app's sys_id this
 * way, so app-repo commands run from inside the project don't need it passed on every invocation.
 * Throws a clear error if no Fluent project is detected (no `now.config.json`, and no `now` field in
 * `package.json`) — there's nothing to default from in that case.
 */
export function resolveAppSysIdFromNowConfig(cwd: string = process.cwd()): string {
    const { NowConfig } = loadBuildCore()
    if (!NowConfig.exists(cwd, fs)) {
        throw new Error(
            `Provide either --scope or --app-sys-id — no now.config.json found in '${cwd}' to default --app-sys-id from. Run this from a Fluent project directory, or pass --scope/--app-sys-id explicitly.`
        )
    }
    return NowConfig.parseFromDirectory(cwd, fs, logger).scopeId
}

/**
 * Defaults `--app-version` from the current directory's `package.json` (`version`), when not
 * explicitly provided. Unlike `resolveAppSysIdFromNowConfig`, this is a soft default — `--app-version`
 * is optional on both `install` and `publish` (each has its own sensible fallback when omitted), so a
 * missing/unreadable `package.json` just means "nothing to default," not an error.
 */
export function resolveAppVersionFromPackageJson(cwd: string = process.cwd()): string | undefined {
    try {
        const { parsePackageJson } = loadBuildCore()
        const version = parsePackageJson(cwd, fs).version
        return typeof version === 'string' && version.length > 0 ? version : undefined
    } catch {
        return undefined
    }
}
